-- Etapa 5. Leitura; escopos geral e delivered se sobrepõem.
WITH c AS (WITH b AS (SELECT x.order_id,x.order_status order_status,dt.dia dia_compra,date_trunc('month',dt.dia)::date mes,l.customer_state uf,l.customer_city cidade,l.membro_tipo localizacao_tipo,c.customer_unique_id FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario dt ON dt.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk LEFT JOIN gold.dim_clientes c ON c.cliente_sk=x.cliente_sk) SELECT customer_unique_id,count(DISTINCT order_id) pedidos,count(DISTINCT order_id) FILTER(WHERE order_status='delivered') delivered,count(DISTINCT dia_compra) FILTER(WHERE order_status='delivered') dias_delivered,min(dia_compra) primeira_compra,max(dia_compra) ultima_compra FROM b WHERE customer_unique_id IS NOT NULL GROUP BY customer_unique_id) SELECT count(*) identidades_observadas,count(*) FILTER(WHERE pedidos>1) multiplos_pedidos,count(*) FILTER(WHERE delivered>=2) multiplos_delivered,count(*) FILTER(WHERE dias_delivered>=1) denominador,count(*) FILTER(WHERE dias_delivered>=2) numerador,100::numeric*count(*) FILTER(WHERE dias_delivered>=2)/nullif(count(*) FILTER(WHERE dias_delivered>=1),0) percentual_descritivo FROM c;
